import{_ as o}from"./index-nktGg5CY.js";import{f as r,g as a,h as s,w as n,i as l,b as d,e as i,k as c}from"./vue-COchWLDO.js";import"./vendor-C0Zqfgkc.js";const m={},p={class:"max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-12"},u={class:"mb-8"};function x(v,e){const t=d("router-link");return i(),r("div",p,[a("div",u,[s(t,{to:"/help",class:"inline-flex items-center text-sm font-medium text-cyan-500 hover:text-cyan-400 dark:text-cyan-400 dark:hover:text-cyan-300 transition-colors"},{default:n(()=>[...e[0]||(e[0]=[a("svg",{class:"mr-2 w-4 h-4",fill:"none",stroke:"currentColor",viewBox:"0 0 24 24"},[a("path",{"stroke-linecap":"round","stroke-linejoin":"round","stroke-width":"2",d:"M10 19l-7-7m0 0l7-7m-7 7h18"})],-1),c(" Volver a Documentación ",-1)])]),_:1})]),e[1]||(e[1]=l('<div class="mb-12"><div class="inline-flex items-center gap-2 px-3 py-1 bg-cyan-500/10 rounded-full mb-4"><span class="text-xs font-medium text-cyan-600 dark:text-cyan-400 uppercase tracking-wider">Dev Studio Workspace</span></div><h1 class="text-3xl sm:text-4xl font-extrabold text-slate-900 dark:text-white mb-4"> Cómo usar Dev Studio y la Memoria Semántica </h1><p class="text-lg text-slate-600 dark:text-slate-400 leading-relaxed"> Dev Studio te permite correr herramientas como Claude Code u OpenCode localmente desde la Web App de MakoClaw, conectadas a tu propia base de datos vectorial para tener memoria de largo plazo en cada proyecto. </p></div><div class="space-y-12"><section><h2 class="text-2xl font-bold text-slate-900 dark:text-white mb-4">1. Desde la Web App</h2><div class="prose prose-slate dark:prose-invert max-w-none text-slate-600 dark:text-slate-400"><p> Al ingresar a <strong>Dev Studio</strong> desde el menú lateral, verás una interfaz dividida en dos paneles: </p><ul class="list-disc pl-6 space-y-2 mt-4"><li><strong>Selección de Proyecto:</strong> A la izquierda, verás un listado de tus proyectos configurados. Hacé clic en uno para conectarte al Bridge local. MakoClaw levantará internamente el proceso del LLM (OpenCode o Claude Code) apuntando a esa carpeta.</li><li><strong>Terminal Stream:</strong> Una vez conectado, el panel central se convierte en tu terminal. Podés enviarle prompts directamente. El motor mantiene aislado el proceso del resto del orquestador de MakoClaw.</li><li><strong>Memoria:</strong> En la pestaña &quot;Memory&quot; vas a encontrar un buscador de memoria semántica. Todo el código, snippets o reglas que guardes ahí, <strong>se inyectan automáticamente</strong> en el prompt inicial del agente cuando mandás un mensaje desde la terminal, usando el embedder local ONNX.</li></ul></div></section><section><h2 class="text-2xl font-bold text-slate-900 dark:text-white mb-4">2. Integración con Telegram</h2><div class="p-6 bg-amber-50 dark:bg-amber-500/10 rounded-2xl border border-amber-200 dark:border-amber-500/20"><div class="flex items-start gap-4"><div class="p-2 bg-amber-100 dark:bg-amber-500/20 rounded-xl flex-shrink-0 text-amber-600 dark:text-amber-400"><svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path></svg></div><div><h3 class="text-lg font-bold text-amber-800 dark:text-amber-300 mb-2">Futura implementación</h3><p class="text-amber-700 dark:text-amber-400 leading-relaxed"> Actualmente, el uso de Dev Studio por Telegram <strong>no está implementado</strong>. Por el momento, la experiencia es 100% interactiva a través del websocket de la <strong>Web App</strong>, ya que el ciclo de vida del proceso de OpenCode requiere stream continuo de texto (stdout/stdin) que no es funcional en mensajes asíncronos cortos como los de Telegram. <br><br> En próximas versiones, expondremos comandos en el bot para consultar el estado del bridge (<code>/dev status</code>) y acceder al motor de búsqueda vectorial local. </p></div></div></div></section><section><h2 class="text-2xl font-bold text-slate-900 dark:text-white mb-4">Requisitos Previos (Importante)</h2><div class="prose prose-slate dark:prose-invert max-w-none text-slate-600 dark:text-slate-400"><p>Para que la herramienta funcione correctamente en tu VPS o máquina local, es importante tener en cuenta:</p><ul class="list-disc pl-6 space-y-2 mt-4"><li>MakoClaw llama a procesos Node a través de <code>pkg/bridge</code>. Es necesario tener NodeJS instalado y funcional en el sistema.</li><li>Para usar OpenCode, es necesario ejecutar <code>npm install -g opencode</code>.</li><li>El modelo de embeddings <code>all-MiniLM-L6-v2</code> será descargado durante la primera ejecución de memoria. Tomará tiempo inicial según la red y puede consumir algo de CPU local debido al procesamiento ONNX nativo en Go.</li></ul></div></section></div>',2))])}const h=o(m,[["render",x]]);export{h as default};
